source:
/* Bài 10 — Class và đối tượng: class, __init__, self, thuộc tính, phương thức, list các đối tượng
   Nhiệm vụ studio: Đúc nhân vật từ khuôn. Mã đồng bộ: chỉ ghi trong README của bài. */
"use strict";
(function () {
const { codeVaManHinh, giaiMa, cuPhap, moRong, meo, luuY, khai, docThem, co, khongCo, dem, W3, DOCS } = window.KIT;

window.LESSON = {
  id: "bai10", number: 10,
  title: "Class và đối tượng",
  story: "Đúc nhân vật từ khuôn",
  skills: ["class", "Đối tượng", "__init__", "self", "Thuộc tính", "Phương thức", "List các đối tượng"],

  errorTable: [
    ["AttributeError: 'NhanVat' object has no attribute 'mau'", "Đọc thuộc tính chưa được gán, hoặc gõ sai tên (Mau, mau1…)", "Gán <code>self.mau = …</code> trong <code>__init__</code>; gõ đúng tên, phân biệt hoa thường"],
    ["TypeError: NhanVat.__init__() missing 1 required positional argument: 'mau'", "Tạo đối tượng thiếu đối số", "Truyền đủ đối số như tham số của <code>__init__</code> (không tính self)"],
    ["TypeError: NhanVat() takes no arguments", "Viết sai tên <code>__init__</code> (thiếu dấu gạch dưới, viết _init_ hay __int__)", "Đúng 2 dấu gạch dưới mỗi bên: <code>__init__</code>"],
    ["TypeError: … takes 1 positional argument but 2 were given", "Quên <code>self</code> ở đầu danh sách tham số của phương thức", "<code>def trung_don(self, sat_thuong):</code>"],
    ["NameError: name 'self' is not defined", "Dùng self trong phương thức nhưng quên khai báo self ở dòng def", "Thêm <code>self</code> làm tham số đầu tiên"],
    ["UnboundLocalError / thuộc tính không đổi", "Viết <code>mau = mau - 30</code> thay vì <code>self.mau</code> trong phương thức", "Trong class luôn viết <code>self.</code> trước thuộc tính"],
    ["In ra &lt;__main__.NhanVat object at 0x…&gt;", "In thẳng cả đối tượng", "In từng thuộc tính, hoặc viết phương thức <code>__str__</code> (Tìm hiểu thêm)"],
    ["Gọi phương thức mà không có gì xảy ra", "Quên cặp ngoặc: <code>kai.di_chuyen</code>", "Gọi phải có ngoặc: <code>kai.di_chuyen(3)</code>"]
  ],

  steps: [
    /* ================= CHẶNG 1 ================= */
    {
      kind: "stage", id: "stage-1", number: 1, nav: "Khuôn và sản phẩm",
      kicker: "CHẶNG 1 · CLASS LÀ KHUÔN, ĐỐI TƯỢNG LÀ SẢN PHẨM",
      title: "class: một khuôn, nhiều nhân vật",
      nova: "Game có 100 nhân vật, mỗi nhân vật có tên, máu, toạ độ… Viết 400 biến thì rối lắm. Ta làm một <b>khuôn</b> (class) rồi <b>đúc</b> bao nhiêu nhân vật cũng được.",
      objectives: ["Hiểu class là khuôn, đối tượng là sản phẩm", "Viết class có __init__", "Tạo đối tượng và đọc thuộc tính bằng dấu chấm"],
      lesson: `
        ${khai("Vì sao cần class?", `<p>Ba nhân vật cần <code>ten1, mau1, ten2, mau2, ten3, mau3</code>. Thêm toạ độ, cấp độ… số biến tăng vọt và rất dễ nhầm. <b>Class</b> gom mọi thông số của <b>một</b> nhân vật lại với nhau. Mỗi nhân vật tạo ra từ class là một <b>đối tượng</b> mang theo thông số của riêng mình.</p>`, "blue")}
        ${codeVaManHinh(`class NhanVat:
    def __init__(self, ten, mau):
        self.ten = ten
        self.mau = mau

kai = NhanVat("Kai", 100)
lia = NhanVat("Lia", 80)
print(kai.ten, kai.mau)
print(lia.ten, lia.mau)`, "Kai 100\nLia 80", "khuon_nhan_vat.py")}
        ${giaiMa("Giải mã class", [
          { code: "class NhanVat:", y: "<b>Khuôn</b> tên <code>NhanVat</code>. Tên class viết hoa chữ cái đầu mỗi từ (NhanVat, QuaiVat).", nhan: true },
          { code: "def __init__(self, ten, mau):", y: "Hàm <b>khởi tạo</b>: chạy <b>tự động</b> mỗi khi đúc một đối tượng mới. Hai dấu gạch dưới mỗi bên." },
          { code: "self.ten = ten", y: "Gán <b>thuộc tính</b> cho đối tượng đang được đúc: <code>self</code> là “chính nhân vật này”." },
          { code: 'kai = NhanVat("Kai", 100)', y: "<b>Đúc</b> một đối tượng. Python tự truyền đối tượng mới vào <code>self</code>; ta chỉ truyền <code>ten</code>, <code>mau</code>.", nhan: true },
          { code: "kai.mau", y: "Đọc thuộc tính bằng <b>dấu chấm</b>: máu của Kai." }
        ])}
        ${cuPhap({ ten: "CLASS VÀ ĐỐI TƯỢNG",
          mau: ["class ‹TênClass›:\n    def __init__(self, ‹tham số›):\n        self.‹thuộc tính› = ‹tham số›", "‹biến› = ‹TênClass›(‹đối số›)", "‹biến›.‹thuộc tính›"],
          quyTac: ["Tên class viết hoa chữ cái đầu mỗi từ: <code>NhanVat</code>", "<code>__init__</code> có 2 dấu gạch dưới mỗi bên; tham số đầu tiên là <code>self</code>", "Khi tạo đối tượng <b>không</b> truyền self. Python tự truyền"],
          viDu: 'class VatPham:\n    def __init__(self, ten, gia):\n        self.ten = ten\n        self.gia = gia\n\nkiem = VatPham("Kiem go", 50)\nprint(kiem.ten, "-", kiem.gia, "xu")', man: "Kiem go - 50 xu" })}
        ${docThem([[W3("python_classes"), "W3Schools: Classes/Objects"], [DOCS("tutorial/classes.html"), "Python Tutorial — Classes"]])}
      `,
      challenges: [
        {
          id: "s1-predict", type: "choice", bet: true, mono: true,
          title: "Hai sản phẩm từ một khuôn",
          prompt: "Hai con quái được đúc từ cùng một khuôn. Terminal hiện gì?",
          code: 'class Quai:\n    def __init__(self, ten, mau):\n        self.ten = ten\n        self.mau = mau\n\na = Quai("Slime", 30)\nb = Quai("Goblin", 50)\nprint(b.ten, a.mau)',
          options: [{ text: "Slime 30", why: "b là Goblin, b.ten là tên của b." }, { text: "Goblin 30" },
                    { text: "Goblin 50", why: "a.mau là máu của Slime, không phải của Goblin." }, { text: "Slime 50", why: "Đọc lại: b.ten rồi a.mau." }],
          answer: "Goblin 30",
          why: "Mỗi đối tượng giữ thông số của riêng mình."
        },
        {
          id: "s1-code", type: "code",
          title: "Khuôn vật phẩm",
          prompt: "Viết class <code>VatPham</code> có hai thuộc tính <code>ten</code> và <code>gia</code>. Phần tạo đối tượng và in kết quả đã có sẵn, đừng sửa.",
          requirements: ["Định nghĩa <code>class VatPham:</code> có <code>__init__(self, ten, gia)</code>.", "Không sửa 5 dòng có sẵn."],
          starter: '# Viet class VatPham o day\n\nkiem = VatPham("Kiem", 50)\nkhien = VatPham("Khien", 70)\nprint(kiem.ten, kiem.gia)\nprint(khien.ten, khien.gia)\nprint("Tong:", kiem.gia + khien.gia)\n',
          expected: "Kiem 50\nKhien 70\nTong: 120",
          rules: [{ test: c => co(c, "class\\s+VatPham\\s*:") && co(c, "def\\s+__init__\\s*\\(\\s*self\\s*,"), msg: "Viết class VatPham: với def __init__(self, ten, gia):" }],
          why: "Một khuôn VatPham đúc được cả kiếm lẫn khiên.",
          hints: ["class VatPham:\n    def __init__(self, ten, gia):", "Trong __init__: self.ten = ten và self.gia = gia"]
        }
      ]
    },

    /* ================= CHẶNG 2 ================= */
    {
      kind: "stage", id: "stage-2", number: 2, nav: "self và thuộc tính",
      kicker: "CHẶNG 2 · SELF VÀ THUỘC TÍNH",
      title: "self: mỗi nhân vật một bộ thông số",
      nova: "Kai trúng đòn thì chỉ máu của Kai giảm, Lia vẫn nguyên. Bí mật nằm ở <b>self</b>, mỗi đối tượng có bộ <b>thuộc tính</b> riêng.",
      objectives: ["Hiểu self là chính đối tượng", "Đặt thuộc tính có giá trị mặc định", "Sửa thuộc tính của một đối tượng"],
      lesson: `
        ${codeVaManHinh(`class NhanVat:
    def __init__(self, ten, mau=100):
        self.ten = ten
        self.mau = mau
        self.x = 0
        self.y = 0

kai = NhanVat("Kai")
lia = NhanVat("Lia", 80)
kai.mau -= 30
lia.x = 5
print(kai.ten, kai.mau, kai.x)
print(lia.ten, lia.mau, lia.x)`, "Kai 70 0\nLia 80 5", "thuoc_tinh.py")}
        ${giaiMa("self và thuộc tính", [
          { code: "self", y: "“Chính đối tượng này”. Khi đúc Kai, <code>self</code> là Kai; khi đúc Lia, <code>self</code> là Lia.", nhan: true },
          { code: "mau=100", y: "Tham số có <b>giá trị mặc định</b> như hàm ở Bài 8: không truyền thì máu là 100." },
          { code: "self.x = 0", y: "Thuộc tính không cần tham số: mọi nhân vật mới đều bắt đầu ở toạ độ 0." },
          { code: "kai.mau -= 30", y: "Sửa thuộc tính của <b>riêng</b> Kai. Lia không bị ảnh hưởng.", nhan: true }
        ])}
        ${luuY("Đọc thuộc tính chưa có, ví dụ <code>kai.mana</code>, Python báo <code>AttributeError: 'NhanVat' object has no attribute 'mana'</code>. Kiểm tra lại tên thuộc tính trong <code>__init__</code>.")}
        ${cuPhap({ ten: "THUỘC TÍNH",
          mau: ["self.‹thuộc tính› = ‹giá trị›        (trong __init__)", "‹đối tượng›.‹thuộc tính› = ‹giá trị mới›   (ngoài class)"],
          quyTac: ["Mỗi đối tượng có bộ thuộc tính riêng", "Thuộc tính chưa gán mà đọc → <code>AttributeError</code>", "Bên trong class luôn viết <code>self.</code> trước thuộc tính"],
          viDu: 'class Quai:\n    def __init__(self, ten, mau=40):\n        self.ten = ten\n        self.mau = mau\n\nq = Quai("Slime")\nq.mau = q.mau - 15\nprint(q.ten, q.mau)', man: "Slime 25" })}
        ${docThem([[W3("python_classes"), "W3Schools: The __init__() Function và self"]])}
      `,
      challenges: [
        {
          id: "s2-predict", type: "choice", bet: true, mono: true,
          title: "Sửa một hộp, hộp kia có đổi?",
          prompt: "Hai đối tượng cùng khuôn, sửa thuộc tính của một đối tượng. Terminal hiện gì?",
          code: "class Hop:\n    def __init__(self, so=1):\n        self.so = so\n\na = Hop()\nb = Hop(5)\na.so += 10\nprint(a.so, b.so)",
          options: [{ text: "11 15", why: "Sửa a không làm b đổi, mỗi đối tượng có thuộc tính riêng." }, { text: "11 5" },
                    { text: "1 5", why: "a.so += 10 đã đổi a.so." }, { text: "15 5", why: "a được tạo không truyền đối số nên a.so bắt đầu là 1." }],
          answer: "11 5",
          why: "Thuộc tính thuộc về từng đối tượng."
        },
        {
          id: "s2-code", type: "code",
          title: "Nhân vật lên cấp",
          prompt: "Viết class <code>NhanVat</code>: thuộc tính <code>ten</code>, <code>mau</code> (mặc định 100) và <code>cap</code> luôn bắt đầu bằng 1. Phần nhập và in đã có sẵn.",
          requirements: ["<code>__init__(self, ten, mau=100)</code>; <code>self.cap = 1</code> không cần tham số.", "Không sửa 4 dòng có sẵn."],
          starter: '# Viet class NhanVat o day\n\nten = input("Ten: ")\np = NhanVat(ten)\np.cap += 1\nprint(p.ten, "- mau", p.mau, "- cap", p.cap)\n',
          tests: [{ input: "Kai", expected: "Ten: Kai\nKai - mau 100 - cap 2" }, { input: "Lia", expected: "Ten: Lia\nLia - mau 100 - cap 2" }],
          rules: [{ test: c => co(c, "mau\\s*=\\s*100") && co(c, "self\\.cap\\s*=\\s*1\\b"), msg: "Đặt mau=100 làm mặc định và self.cap = 1 trong __init__." }],
          why: "Thuộc tính mặc định giúp đúc nhân vật nhanh mà vẫn đủ thông số.",
          hints: ["def __init__(self, ten, mau=100):", "self.ten = ten · self.mau = mau · self.cap = 1"]
        }
      ]
    },

    /* ================= ĐIỂM DỪNG 1 ================= */
    {
      kind: "gate", id: "gate-1", nav: "Điểm dừng 1", kicker: "ĐIỂM DỪNG 1",
      codeHash: "6914BFCF",
      todo: ["Nghe thầy <b>chốt</b>: class, đối tượng, __init__, self, thuộc tính.",
             "<b>Ghi bài</b> vào vở theo slide.", "Trả lời <b>2 câu ClassPoint</b>.",
             "<b>Luyện tập nhóm 1</b> trên VS Code, chụp ảnh nộp ClassPoint.", "Nhập <b>mã đồng bộ</b> để mở Chặng 3."],
      challenges: [
        {
          id: "g1-bonus", type: "code", bonus: true,
          title: "Khuôn vũ khí",
          prompt: "Trong lúc chờ: viết class <code>VuKhi</code> có <code>ten</code>, <code>sat_thuong</code> và <code>do_ben</code> luôn bắt đầu bằng 10. Nhập tên, sát thương; tạo vũ khí rồi in theo mẫu.",
          requirements: ['Câu dẫn <code>"Ten vu khi: "</code>, <code>"Sat thuong: "</code> (số nguyên).', "Dòng cuối: <code>‹tên›: sat thuong ‹s›, do ben 10</code>."],
          starter: "",
          tests: [{ input: "Kiem\n12", expected: "Ten vu khi: Kiem\nSat thuong: 12\nKiem: sat thuong 12, do ben 10" },
                  { input: "Cung\n8", expected: "Ten vu khi: Cung\nSat thuong: 8\nCung: sat thuong 8, do ben 10" }],
          rules: [{ test: c => co(c, "class\\s+VuKhi\\s*:") && co(c, "self\\.do_ben\\s*=\\s*10"), msg: "Viết class VuKhi với self.do_ben = 10." }],
          why: "Thuộc tính cố định lúc đúc: mọi vũ khí mới đều có độ bền 10.",
          hints: ["class VuKhi:\n    def __init__(self, ten, sat_thuong):\n        self.ten = ten\n        self.sat_thuong = sat_thuong\n        self.do_ben = 10", 'print(f"{v.ten}: sat thuong {v.sat_thuong}, do ben {v.do_ben}")']
        }
      ]
    },

    /* ================= CHẶNG 3 ================= */
    {
      kind: "stage", id: "stage-3", number: 3, nav: "Phương thức",
      kicker: "CHẶNG 3 · PHƯƠNG THỨC",
      title: "Phương thức: kỹ năng gắn với nhân vật",
      nova: "Ở Bài 8, kỹ năng là hàm đứng riêng. Giờ ta đặt hàm <b>vào trong</b> class, gọi là <b>phương thức</b>. Mỗi nhân vật tự di chuyển, tự trúng đòn bằng chính thông số của mình.",
      objectives: ["Viết phương thức có tham số self", "Gọi phương thức bằng dấu chấm", "Phương thức sửa thuộc tính và trả về giá trị"],
      lesson: `
        ${codeVaManHinh(`class NhanVat:
    def __init__(self, ten, mau=100):
        self.ten = ten
        self.mau = mau
        self.x = 0

    def di_chuyen(self, dx):
        self.x += dx

    def trung_don(self, sat_thuong):
        self.mau = max(self.mau - sat_thuong, 0)

    def con_song(self):
        return self.mau > 0

kai = NhanVat("Kai", 50)
kai.di_chuyen(3)
kai.trung_don(20)
print(kai.x, kai.mau, kai.con_song())
kai.trung_don(40)
print(kai.mau, kai.con_song())`, "3 30 True\n0 False", "phuong_thuc.py")}
        ${giaiMa("Giải mã phương thức", [
          { code: "def di_chuyen(self, dx):", y: "<b>Phương thức</b> = hàm nằm trong class. Tham số đầu tiên <b>luôn</b> là <code>self</code>.", nhan: true },
          { code: "kai.di_chuyen(3)", y: "Gọi bằng dấu chấm. Python tự truyền <code>kai</code> vào <code>self</code>, còn <code>3</code> vào <code>dx</code>." },
          { code: "self.x += dx", y: "Sửa thuộc tính của <b>đúng</b> đối tượng đã gọi phương thức.", nhan: true },
          { code: "return self.mau > 0", y: "Phương thức cũng <code>return</code> được như hàm thường: <code>con_song()</code> trả về True/False." }
        ])}
        ${cuPhap({ ten: "PHƯƠNG THỨC",
          mau: ["def ‹tên›(self, ‹tham số›):\n    ‹dùng self.‹thuộc tính››", "‹đối tượng›.‹tên›(‹đối số›)"],
          quyTac: ["Tham số đầu tiên luôn là <code>self</code>", "Gọi phương thức <b>không</b> truyền self; nhớ cặp ngoặc", "Quên self ở dòng def → <code>TypeError … takes 1 positional argument but 2 were given</code>"],
          viDu: "class Quai:\n    def __init__(self, mau):\n        self.mau = mau\n\n    def hoi_mau(self, luong):\n        self.mau += luong\n        return self.mau\n\nq = Quai(20)\nprint(q.hoi_mau(15))", man: "35" })}
        ${docThem([[W3("python_classes"), "W3Schools: Object Methods"], [DOCS("tutorial/classes.html#method-objects"), "Python Tutorial — Method Objects"]])}
      `,
      challenges: [
        {
          id: "s3-predict", type: "choice", bet: true, mono: true,
          title: "Bộ đếm",
          prompt: "Phương thức <code>tang</code> được gọi 3 lần. Terminal hiện gì?",
          code: "class Dem:\n    def __init__(self):\n        self.so = 0\n\n    def tang(self, buoc=1):\n        self.so += buoc\n\nd = Dem()\nd.tang()\nd.tang(5)\nd.tang()\nprint(d.so)",
          options: [{ text: "7" }, { text: "6", why: "Cộng lại: 1 + 5 + 1." }, { text: "1", why: "Mỗi lần gọi cộng dồn vào self.so, không tạo lại từ 0." },
                    { text: "0", why: "Phương thức đã sửa self.so." }],
          answer: "7",
          why: "Thuộc tính giữ giá trị giữa các lần gọi phương thức."
        },
        {
          id: "s3-code", type: "code",
          title: "Quái trúng đòn",
          prompt: "Class <code>Quai</code> đã có <code>__init__</code>. Viết thêm hai phương thức: <code>trung_don(self, st)</code> trừ máu (không xuống dưới 0) và <code>con_song(self)</code> trả về True/False.",
          requirements: ['Câu dẫn <code>"Mau: "</code> đã có sẵn.', "Không sửa phần chương trình chính."],
          starter: 'class Quai:\n    def __init__(self, ten, mau):\n        self.ten = ten\n        self.mau = mau\n\n    # Viet phuong thuc trung_don va con_song o day\n\nq = Quai("Goblin", int(input("Mau: ")))\nq.trung_don(25)\nprint(q.ten, q.mau, q.con_song())\nq.trung_don(25)\nprint(q.ten, q.mau, q.con_song())\n',
